use rk3588_boot_support::Mmio8;use crate::stage13::ArchTimerIo;use crate::stage14::{DdrSequenceError,DdrTrainer};
pub trait EarlyDdrRuntime:ArchTimerIo+crate::stage12::DebugUartIo+Mmio8{}impl<T:ArchTimerIo+crate::stage12::DebugUartIo+Mmio8> EarlyDdrRuntime for T{}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct EarlyDdrReport{pub probe_byte:u8,pub uart_base:u64,pub baud:u32}
pub fn run_early_ddr_entry<I:EarlyDdrRuntime,T:DdrTrainer>(io:&mut I,trainer:&mut T,uart_base:u64,baud:u32)->Result<EarlyDdrReport,DdrSequenceError<T::Error>>{crate::stage13::init_arch_timer(io);crate::stage12::init_debug_uart(io,uart_base,baud);let probe_byte=crate::stage14::run_ddr_probe_and_train(io,trainer)?;Ok(EarlyDdrReport{probe_byte,uart_base,baud})}
#[cfg(test)]mod tests{use super::*;use rk3588_boot_support::{BarrierOps,DelayUs,Mmio32};struct I{freq:u32,status:u32,probe:u8}impl Mmio32 for I{fn read32(&mut self,a:u64)->u32{if a==crate::stage14::DDR_PROBE_BASE+0x84{self.status}else{0}}fn write32(&mut self,a:u64,v:u32){if a==crate::stage14::DDR_PROBE_BASE+0x84&&v==15{self.status=3}}}impl Mmio8 for I{fn read8(&mut self,a:u64)->u8{if a==crate::stage14::DDR_PROBE_BASE+0x22{self.probe}else{0}}}impl DelayUs for I{fn delay_us(&mut self,_:u32){}}impl BarrierOps for I{fn dsb(&mut self){}fn isb(&mut self){}}impl ArchTimerIo for I{fn write_cntfrq_el0(&mut self,h:u32){self.freq=h}}impl crate::stage12::DebugUartIo for I{fn write32(&mut self,_:u64,_:u32){}}struct T(u8);impl DdrTrainer for T{type Error=();fn train(&mut self,p:u8)->Result<(),()>{self.0=p;Ok(())}}#[test]fn early(){let mut i=I{freq:0,status:0,probe:0x5a};let mut t=T(0);let r=run_early_ddr_entry(&mut i,&mut t,0xFE66_0000,115200).unwrap();assert_eq!(i.freq,24_000_000);assert_eq!(r.probe_byte,0x5a);assert_eq!(t.0,0x5a);}}
